(()=>{const tracks=[...document.querySelectorAll('.cargo-track')],section=document.getElementById('pillars-of-pyrite-section'),about=document.getElementById('esc-about'),bg=about?.querySelector('.esc-cove-bg'),reduce=matchMedia('(prefers-reduced-motion:reduce)');let frame=0;function draw(){frame=0;if(document.hidden)return;const progress=section?innerHeight-section.getBoundingClientRect().top:0;tracks.forEach((track,i)=>{if(reduce.matches){track.style.transform='';return}const cycle=track.firstElementChild.offsetWidth;const amount=cycle*.4+progress*(i%2?.28:-.28);const x=-((amount%cycle+cycle)%cycle);track.style.transform=`translate3d(${x}px,0,0)`});if(bg)bg.style.transform='none';const stage=document.querySelector('.book-scroll-stage'),scene=stage?.querySelector('.book-scene');const held=stage&&scene&&!reduce.matches?Math.max(0,Math.min((parseFloat(getComputedStyle(scene).top)||90)-stage.getBoundingClientRect().top,stage.offsetHeight-scene.offsetHeight)):0;about?.querySelectorAll('.esc-cove-anchor,.esc-cove-waves').forEach(el=>el.style.transform=`translate3d(0,${held}px,0)`);}function schedule(){if(!frame)frame=requestAnimationFrame(draw)}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});reduce.addEventListener('change',schedule);draw()})();
